var SKILLS = Object.freeze([
  {
    id: "empirical-init",
    title: "Empirical Init",
    description: "Explicitly initialize or repair Empirical in the current repository; use only when the user asks for setup or repair.",
    entryOperation: "init",
    stopCondition: "Setup applied, repaired, cancelled, blocked, or awaiting human input."
  }
]);
function assertRegistryIntegrity() {
  const operationIds = new Set;
  const mcpNames = new Set;
  const verbs = new Set;
  const handlers = new Set;
  for (const entry of OPERATIONS) {
    if (entry.readOnly && entry.destructive) {
      throw new Error(`Operation ${entry.id} cannot be both read-only and destructive.`);
    }
    for (const [label, value, set2] of [
      ["operation id", entry.id, operationIds],
      ["MCP name", entry.mcpName, mcpNames],
      ["internal verb", entry.internalVerb, verbs],
      ["handler", entry.handler, handlers]
    ]) {
      if (set2.has(value)) {
        throw new Error(`Duplicate ${label}: ${value}`);
      }
      set2.add(value);
    }
  }
  const skillIds = new Set;
  for (const skill of SKILLS) {
    if (skillIds.has(skill.id)) {
      throw new Error(`Duplicate skill id: ${skill.id}`);
    }
    skillIds.add(skill.id);
    if (!operationIds.has(skill.entryOperation)) {
      throw new Error(`Skill ${skill.id} refers to unknown operation ${skill.entryOperation}.`);
    }
  }
}
assertRegistryIntegrity();
function operationById(id) {
  return OPERATIONS.find((entry) => entry.id === id);
}
function operationAnnotations(id) {
  const definition = operationById(id);
  if (!definition)
    throw new Error(`Unknown operation metadata: ${id}`);
  return {
    readOnlyHint: definition.readOnly,
    destructiveHint: definition.destructive,
    idempotentHint: definition.idempotent
  };
}

